import {mountExperiment} from '../model-kit/session.js';
import {attachCardDrag} from '../shared/drag.js';
import {definition} from '../../../embed/definitions/lab-clocks.js';
import {DAYS,LANES,SCENARIOS,scheduled,simulate,compare,needAt,format,describe} from './model.js';
const e=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(s,{pinned}){const r=simulate(s),b=compare(s,pinned);const days=Array.from({length:DAYS},(_,i)=>i+1);
return `<section class="clocks-situation"><label for="clocks-scenario">External event stream<select id="clocks-scenario">${Object.entries(SCENARIOS).map(([id,x])=>`<option value="${id}" ${s.scenario===id?'selected':''}>${e(x.name)}</option>`).join('')}</select></label><p>${e(SCENARIOS[s.scenario].detail)} A and B stand for two different things people need.</p></section>
<div class="clocks-verdict"><div><strong>${r.matches}</strong><span>actions match the need</span></div><div><strong>${r.outdated}</strong><span>actions use an outdated need</span></div><div><strong>${r.unused}</strong><span>delivery slots unused</span></div><div><strong>${r.attentionUsed} / ${s.attention}</strong><span>review attention used</span></div></div>
<section aria-labelledby="clocks-title"><h2 id="clocks-title">Move the clocks</h2><p class="clocks-intro">Drag a first event along its row, tap a day, or edit First day. The interval repeats from that day. Scroll sideways to explore all 28 days.</p><div class="clocks-scroll" tabindex="0" role="region" aria-label="28-day clock canvas; scroll horizontally"><div class="clocks-canvas">
<div class="clock-scale"><span>Day</span><div class="clock-cells">${days.map(d=>`<span>${d}</span>`).join('')}</div></div><div class="clock-needs"><strong>Actual need</strong><div class="clock-cells">${days.map(d=>`<span class="${needAt(s,d)==='B'?'need-b':''}">${needAt(s,d)}</span>`).join('')}</div></div>
${LANES.map(l=>{const times=scheduled(s.clocks[l.id]);return `<section class="clock-row" aria-label="${e(l.name)}"><header><h3>${e(l.name)} <small>${l.verb}</small></h3><div><label for="clock-${l.id}-start">First day<input type="number" id="clock-${l.id}-start" min="1" max="28" step="1" data-lane="${l.id}" data-field="start" value="${s.clocks[l.id].start}"></label><label for="clock-${l.id}-every">Every<input type="number" id="clock-${l.id}-every" min="1" max="28" step="1" data-lane="${l.id}" data-field="every" value="${s.clocks[l.id].every}">days</label></div></header><div class="clock-cells">${days.map(day=>{const first=day===s.clocks[l.id].start,event=r.trace.find(t=>t.day===day&&t.lane===l.id),label=first?'↔':event?.status==='skipped'?'×':event?.status==='waiting'?'–':event?.status==='matched'?'✓':event?.status==='outdated'?'!':times.includes(day)?'●':'·';return `<div data-drop-id="${l.id}:${day}" ${first?`data-drag-id="${l.id}"`:''}><button type="button" class="clock-day ${times.includes(day)?'scheduled':''} ${first?'first-event':''} ${event?.status||''}" id="day-${l.id}-${day}" data-day="${day}" data-clock="${l.id}" ${first?'data-drag-handle':''} aria-label="Set ${e(l.name)} first day to ${day}${first?'; current first event':''}" title="${e(event?.detail||'No event. Tap to start here.')}">${label}</button></div>`;}).join('')}</div></section>`;}).join('')}
</div></div><p class="clock-key">↔ first event · ● event · – waiting · × skipped review · ✓ matching action · ! outdated action</p></section>
<section class="clocks-attention" aria-label="Attention assumptions"><label for="clocks-review-cost">Attention per review<input id="clocks-review-cost" type="number" min="0" max="3" step="0.25" value="${s.reviewCost}"></label><label for="clocks-attention">Total review attention<input id="clocks-attention" type="number" min="0" max="30" step="0.25" value="${s.attention}"></label><p>Each held review spends attention, including a review without evidence. ${r.skipped} reviews are skipped when attention runs out. Units are your assumption.</p></section>
<section class="experiment-output" aria-labelledby="clocks-outcome"><h2 id="clocks-outcome">Where evidence waits</h2><p>${r.deliveries.length?`At action time, evidence is ${format(r.averageAge)} days old on average. The chain spends ${format(r.averageReviewWait)} days before review, ${format(r.averageFundingWait)} before funding and ${format(r.averageDeliveryWait)} before acting.`:'No funded choice reaches a delivery slot. The event trace shows which handoff is missing.'} Older evidence can still describe the current need.</p>${b?`<h3>Pinned clocks · same external events and attention rules</h3><div class="table-scroll"><table><thead><tr><th>Timing</th><th>Matching</th><th>Outdated</th><th>Unused slots</th><th>Attention used</th></tr></thead><tbody><tr><th>Current</th><td>${r.matches}</td><td>${r.outdated}</td><td>${r.unused}</td><td>${r.attentionUsed}</td></tr><tr><th>Pinned</th><td>${b.matches}</td><td>${b.outdated}</td><td>${b.unused}</td><td>${b.attentionUsed}</td></tr></tbody></table></div><p class="clocks-intro">Only the four clocks differ. Changing the event stream, attention or review cost replays both timings.</p>`:''}
<h3>At each delivery opportunity</h3><ol class="clock-deliveries">${r.trace.filter(t=>t.lane==='delivery').map(t=>`<li><strong>Day ${t.day} · ${t.status}</strong><p>${e(t.detail)}</p></li>`).join('')}</ol></section>
<details id="clocks-trace"><summary>Trace every observation, choice and authorisation</summary><ol class="clock-trace">${r.trace.map(t=>`<li><strong>Day ${t.day} · ${e(t.name)}</strong><span>${e(t.detail)}</span></li>`).join('')}</ol></details>
<details id="clocks-limits"><summary>Mechanism, counterexample and source</summary><p>Same-day order is discovery → review → funding → delivery. At the start there is no observation, choice or funding. Discovery perfectly observes the current need. Review chooses the latest observation available, funding copies the latest reviewed choice, and delivery acts on the latest funded choice. Later evidence never rewrites an earlier action.</p><p>Choices and funding do not expire. Every delivery slot repeats the latest funded action, so counts describe action opportunities, not value delivered. Review attention is a separate finite budget; it does not remove delivery capacity. The event stream is known to you as the experimenter, but each stage can use only information already passed to it.</p><p>Try the steady-need scenario: more frequent reviews may spend more attention with no change in actions. In a changing scenario, early reviews can exhaust attention before the change. No clock arrangement is universally best.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-2052-questions-and-context">Questions and Context</a>. The four-stage timing mechanism is an explicit design for this experiment.</p></details>`;
}
function bind({root,state,change,report}){const update=(edit,message)=>{const next=structuredClone(state);edit(next);change(next,message);};
const click=event=>{const b=event.target.closest('button[data-day]');if(b)update(s=>{s.clocks[b.dataset.clock].start=Number(b.dataset.day);},'First event moved. The whole schedule replays.');};
const input=event=>{const el=event.target;if(el.dataset.lane)update(s=>{s.clocks[el.dataset.lane][el.dataset.field]=Number(el.value);},'Clock changed. The whole schedule replays.');if(el.id==='clocks-scenario')update(s=>{s.scenario=el.value;},'External events changed for current and pinned clocks.');if(el.id==='clocks-review-cost')update(s=>{s.reviewCost=Number(el.value);},'Attention cost changed.');if(el.id==='clocks-attention')update(s=>{s.attention=Number(el.value);},'Review attention budget changed.');};
root.addEventListener('click',click);root.addEventListener('change',input);
const drag=attachCardDrag({root,horizontalScrollContainer:root.querySelector('.clocks-scroll'),onDrop:({itemId,dropId})=>{const [lane,day]=dropId.split(':');if(lane!==itemId){report('Move this event within its own row.');return;}update(s=>{s.clocks[lane].start=Number(day);},'Clock moved. The whole schedule replays.');}});
return()=>{drag();root.removeEventListener('click',click);root.removeEventListener('change',input);};
}
await mountExperiment({route:'clocks',definition,render,bind,describe});
